L["Opens a box with the build number, what this client allows, the settings that change what it does and anything that has broken -- ready to select and paste."] = "Abre uma caixa com o número da versão, o que este cliente permite, as configurações que mudam o que o addon faz e tudo o que deu erro -- pronta para selecionar e colar."
L["Switched off -- no prompt will appear."] = "Desativado -- nenhum lembrete vai aparecer."
L["Snoozed until %s, %s from now -- no prompt until then."] = "Em soneca até %s, daqui a %s -- nenhum lembrete até lá."
L["Nothing to do: %s"] = "Nada a fazer: %s"
L["Nothing to cast on this character -- /manners debug says why."] = "Nada para lançar neste personagem -- /manners debug diz por quê."
L["Nothing will be offered: %s."] = "Nada será oferecido: %s."
L["Nothing learned to cast yet."] = "Nenhum feitiço aprendido para lançar ainda."
L["Watching for people to buff."] = "De olho em quem pode receber bônus."
L["Held in combat -- the prompt moves on once the fight ends."] = "Congelado em combate -- o lembrete avança quando o combate terminar."
